import{_ as i,c as a,o,a2 as t}from"./chunks/framework.CIiVzG-O.js";const u=JSON.parse('{"title":"使い方ガイド","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/usage.md","filePath":"ja/guide/usage.md","lastUpdated":1793163976000}'),r={name:"ja/guide/usage.md"};function e(n,l,d,s,h,g){return o(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="使い方ガイド" tabindex="-1">使い方ガイド <a class="header-anchor" href="#使い方ガイド" aria-label="Permalink to &quot;使い方ガイド&quot;">​</a></h1><h2 id="アーカイブを開く" tabindex="-1">アーカイブを開く <a class="header-anchor" href="#アーカイブを開く" aria-label="Permalink to &quot;アーカイブを開く&quot;">​</a></h2><h3 id="ダブルクリックで開く" tabindex="-1">ダブルクリックで開く <a class="header-anchor" href="#ダブルクリックで開く" aria-label="Permalink to &quot;ダブルクリックで開く&quot;">​</a></h3><p>NueZip は、対応するすべてのアーカイブフォーマットのデフォルトハンドラーとして自身を登録します。アーカイブファイル（<code>.zip</code>、<code>.rar</code>、<code>.7z</code>、<code>.tar</code>、<code>.gz</code>、<code>.bz2</code>、<code>.xz</code>、<code>.zst</code>）をダブルクリックするだけで、NueZip のメインウィンドウで開きます。</p><h3 id="nuezip-で開く-finder-コンテキストメニュー" tabindex="-1">NueZip で開く（Finder コンテキストメニュー） <a class="header-anchor" href="#nuezip-で開く-finder-コンテキストメニュー" aria-label="Permalink to &quot;NueZip で開く（Finder コンテキストメニュー）&quot;">​</a></h3><p>任意のアーカイブファイルを右クリックし、コンテキストメニューから <strong>NueZip で開く</strong> を選択します。Finder 機能拡張は次のクイックアクションも提供します：</p><ul><li><strong>ここに展開</strong> — アーカイブの内容を現在のフォルダに展開する</li><li><strong>&quot;フォルダ名/&quot; に展開</strong> — 名前付きのサブフォルダに展開する</li><li><strong>ZIP に圧縮</strong> — 選択したファイル／フォルダを ZIP アーカイブに圧縮する</li><li><strong>NueZip で開く</strong> — メインのブラウザウィンドウで開く</li></ul><h3 id="トレイにドラッグ-ドロップ" tabindex="-1">トレイにドラッグ＆ドロップ <a class="header-anchor" href="#トレイにドラッグ-ドロップ" aria-label="Permalink to &quot;トレイにドラッグ＆ドロップ&quot;">​</a></h3><p>アーカイブファイルを NueZip のメニューバーアイコンにドラッグすると、ドロップパネルですばやく開き、即座にアクセスできます。ファイルをトレイアイコンにドラッグして圧縮することもできます。</p><h2 id="アーカイブの展開" tabindex="-1">アーカイブの展開 <a class="header-anchor" href="#アーカイブの展開" aria-label="Permalink to &quot;アーカイブの展開&quot;">​</a></h2><h3 id="基本的な展開" tabindex="-1">基本的な展開 <a class="header-anchor" href="#基本的な展開" aria-label="Permalink to &quot;基本的な展開&quot;">​</a></h3><ol><li>NueZip でアーカイブを開く</li><li>ツールバーの <strong>展開</strong> ボタンをクリックする</li><li>出力先フォルダを選択する</li><li><strong>展開</strong> をクリックする</li></ol><h3 id="finder-からのクイック展開" tabindex="-1">Finder からのクイック展開 <a class="header-anchor" href="#finder-からのクイック展開" aria-label="Permalink to &quot;Finder からのクイック展開&quot;">​</a></h3><p>Finder でアーカイブを右クリックし、次のクイックアクションのいずれかを選択します：</p><ul><li><strong>ここに展開</strong> — 現在のフォルダに直接展開する</li><li><strong>&quot;[アーカイブ名]/&quot; に展開</strong> — 整理された状態になるよう、名前付きのサブフォルダに展開する</li></ul><h3 id="パスワード付きで展開" tabindex="-1">パスワード付きで展開 <a class="header-anchor" href="#パスワード付きで展開" aria-label="Permalink to &quot;パスワード付きで展開&quot;">​</a></h3><p>パスワードで保護されたアーカイブの場合、NueZip はパスワードを求めます。内蔵のパスワードマネージャーは、資格情報をローカルのキーチェーンに安全に保存し、将来の使用に備えることができます。</p><h2 id="アーカイブの圧縮" tabindex="-1">アーカイブの圧縮 <a class="header-anchor" href="#アーカイブの圧縮" aria-label="Permalink to &quot;アーカイブの圧縮&quot;">​</a></h2><h3 id="新しいアーカイブを作成する" tabindex="-1">新しいアーカイブを作成する <a class="header-anchor" href="#新しいアーカイブを作成する" aria-label="Permalink to &quot;新しいアーカイブを作成する&quot;">​</a></h3><ol><li>NueZip のメインウィンドウでファイルまたはフォルダを選択する</li><li>ツールバーの <strong>圧縮</strong> ボタンをクリックする</li><li>アーカイブフォーマットを選択する（ZIP、7z、TAR、GZIP など）</li><li>圧縮設定（レベル、暗号化方式）を構成する</li><li><strong>圧縮</strong> をクリックする</li></ol><h3 id="finder-から圧縮する" tabindex="-1">Finder から圧縮する <a class="header-anchor" href="#finder-から圧縮する" aria-label="Permalink to &quot;Finder から圧縮する&quot;">​</a></h3><p>Finder でファイル／フォルダを右クリックし、<strong>NueZip で圧縮</strong> を選択します：</p><ul><li><strong>ZIP に圧縮</strong> — すばやく ZIP アーカイブを作成する</li><li><strong>オプションを指定して圧縮</strong> — 詳細設定を指定して NueZip を開く</li></ul><h3 id="ドラッグ-ドロップで圧縮する" tabindex="-1">ドラッグ＆ドロップで圧縮する <a class="header-anchor" href="#ドラッグ-ドロップで圧縮する" aria-label="Permalink to &quot;ドラッグ＆ドロップで圧縮する&quot;">​</a></h3><p>ファイルを NueZip のメニューバートレイアイコンにドラッグすると、すばやく ZIP アーカイブを作成できます。</p><h2 id="バッチ操作" tabindex="-1">バッチ操作 <a class="header-anchor" href="#バッチ操作" aria-label="Permalink to &quot;バッチ操作&quot;">​</a></h2><h3 id="バッチ圧縮" tabindex="-1">バッチ圧縮 <a class="header-anchor" href="#バッチ圧縮" aria-label="Permalink to &quot;バッチ圧縮&quot;">​</a></h3><ol><li>NueZip で複数の項目を選択する</li><li>ツールバーまたはファイルメニューから <strong>バッチ圧縮</strong> を選択する</li><li>各項目は別々のアーカイブに圧縮されます</li></ol><h3 id="バッチ展開" tabindex="-1">バッチ展開 <a class="header-anchor" href="#バッチ展開" aria-label="Permalink to &quot;バッチ展開&quot;">​</a></h3><ol><li>NueZip で複数のアーカイブを選択する</li><li>ツールバーまたはファイルメニューから <strong>バッチ展開</strong> を選択する</li><li>すべてのアーカイブが同時に展開されます</li></ol><h3 id="バッチ変換" tabindex="-1">バッチ変換 <a class="header-anchor" href="#バッチ変換" aria-label="Permalink to &quot;バッチ変換&quot;">​</a></h3><ol><li>1 つ以上のアーカイブを選択する</li><li><strong>変換</strong> を選択 → ターゲットフォーマットを選択する</li><li>NueZip は各アーカイブを選択したフォーマットに再圧縮します</li></ol><h3 id="バッチ暗号化" tabindex="-1">バッチ暗号化 <a class="header-anchor" href="#バッチ暗号化" aria-label="Permalink to &quot;バッチ暗号化&quot;">​</a></h3><ol><li>複数の ZIP アーカイブを選択する</li><li><strong>バッチ暗号化</strong> を選択する</li><li>パスワードを設定する — 選択したすべてのアーカイブがパスワードで保護されます</li></ol><h2 id="フォーマット変換" tabindex="-1">フォーマット変換 <a class="header-anchor" href="#フォーマット変換" aria-label="Permalink to &quot;フォーマット変換&quot;">​</a></h2><p>対応する任意のフォーマット間でアーカイブを変換します：</p><ol><li>アーカイブを開く</li><li>ツールバーの <strong>変換</strong> をクリックする</li><li>ターゲットフォーマットを選択する（例：RAR → ZIP、7z → TAR.GZ）</li><li>出力先を選択する</li><li><strong>変換</strong> をクリックする</li></ol><h2 id="アーカイブ修復" tabindex="-1">アーカイブ修復 <a class="header-anchor" href="#アーカイブ修復" aria-label="Permalink to &quot;アーカイブ修復&quot;">​</a></h2><p>破損した RAR または ZIP アーカイブの場合：</p><ol><li>破損したアーカイブを開く</li><li>ツールバーの <strong>修復</strong> をクリックする</li><li>NueZip はアーカイブデータの再構築を試みます</li><li>修復されたアーカイブは新しいファイルとして保存されます</li></ol><h2 id="アーカイブ検索" tabindex="-1">アーカイブ検索 <a class="header-anchor" href="#アーカイブ検索" aria-label="Permalink to &quot;アーカイブ検索&quot;">​</a></h2><p>アーカイブ内の特定のファイルを検索します：</p><ol><li>ツールバーの <strong>検索</strong> ボタンをクリックする</li><li>ファイル名のパターンを入力する</li><li>NueZip は開いているアーカイブ内のすべての項目を検索します</li><li>結果はクイックナビゲーションのための完全なパスとともに表示されます</li></ol><h2 id="パフォーマンスベンチマーク" tabindex="-1">パフォーマンスベンチマーク <a class="header-anchor" href="#パフォーマンスベンチマーク" aria-label="Permalink to &quot;パフォーマンスベンチマーク&quot;">​</a></h2><p>システムの圧縮パフォーマンスをテストします：</p><ol><li><strong>ツール → ベンチマーク</strong> に移動する</li><li>NueZip はさまざまなフォーマットと設定を使用して圧縮テストを実行します</li><li>結果には各フォーマットの圧縮速度（MB/秒）と比率が表示されます</li><li>これを使用して、異なる圧縮方式のパフォーマンスを比較できます</li></ol><h2 id="マルチボリューム-分割-アーカイブ" tabindex="-1">マルチボリューム（分割）アーカイブ <a class="header-anchor" href="#マルチボリューム-分割-アーカイブ" aria-label="Permalink to &quot;マルチボリューム（分割）アーカイブ&quot;">​</a></h2><p>大容量データ用に分割アーカイブを作成します：</p><ol><li>圧縮中に <strong>ボリュームに分割</strong> を有効にする</li><li>ボリュームサイズを選択する（例：100 MB、650 MB、4.7 GB、またはカスタム）</li><li>NueZip は連番のパートファイル（<code>.zip.001</code>、<code>.zip.002</code> など）を作成します</li><li>展開するには、最初のパートファイルを開きます — NueZip は残りを自動的に読み込みます</li></ol><ul><li><strong>パスワード</strong>: 暗号化されたアーカイブのパスワードを指定する</li><li><strong>フォルダで囲む</strong>: アーカイブに単一のルートディレクトリがない場合、ルートフォルダを自動的に作成する</li><li><strong>展開後に開く</strong>: 完了時に Finder で展開されたファイルを表示する</li><li><strong>壊れたファイルを保持</strong>: エラー発生前に展開されたファイルを保持する（部分的な復元用）</li><li><strong>更新モード</strong>: 既存ファイルの処理方法（上書き、スキップ、リネーム）を選択する</li></ul><h3 id="バッチ展開-1" tabindex="-1">バッチ展開 <a class="header-anchor" href="#バッチ展開-1" aria-label="Permalink to &quot;バッチ展開&quot;">​</a></h3><ol><li><strong>ツール → バッチ展開</strong> に移動する</li><li><strong>ファイルを追加...</strong> をクリックしてアーカイブファイルを選択する</li><li>出力先フォルダを選択する</li><li>必要に応じて <strong>展開後に元ファイルを削除</strong> を有効にする</li><li><strong>開始</strong> をクリックする</li></ol><h2 id="アーカイブの作成" tabindex="-1">アーカイブの作成 <a class="header-anchor" href="#アーカイブの作成" aria-label="Permalink to &quot;アーカイブの作成&quot;">​</a></h2><h3 id="ファイルを圧縮する" tabindex="-1">ファイルを圧縮する <a class="header-anchor" href="#ファイルを圧縮する" aria-label="Permalink to &quot;ファイルを圧縮する&quot;">​</a></h3><ol><li>ツールバーの <strong>圧縮</strong> ボタンをクリックする</li><li>圧縮するファイルを選択する（またはウィンドウにドラッグ＆ドロップする）</li><li><strong>アーカイブフォーマット</strong> を選択する：ZIP、7Z、TAR、GZIP、BZIP2</li><li><strong>圧縮方式</strong> とレベルを構成する</li><li><strong>保存場所</strong> とアーカイブ名を設定する</li><li>必要に応じて暗号化用の <strong>パスワード</strong> を設定する</li><li>必要に応じてマルチボリュームアーカイブ用の <strong>分割サイズ</strong> を設定する</li><li><strong>圧縮</strong> をクリックする</li></ol><h3 id="既存のアーカイブにファイルを追加" tabindex="-1">既存のアーカイブにファイルを追加 <a class="header-anchor" href="#既存のアーカイブにファイルを追加" aria-label="Permalink to &quot;既存のアーカイブにファイルを追加&quot;">​</a></h3><ol><li>NueZip で既存のアーカイブを開く</li><li>ツールバーの <strong>ファイルを追加</strong> をクリックする</li><li>追加するファイルを選択する</li><li><strong>追加</strong> をクリックする</li></ol><h2 id="バッチ操作-1" tabindex="-1">バッチ操作 <a class="header-anchor" href="#バッチ操作-1" aria-label="Permalink to &quot;バッチ操作&quot;">​</a></h2><h3 id="バッチ圧縮-1" tabindex="-1">バッチ圧縮 <a class="header-anchor" href="#バッチ圧縮-1" aria-label="Permalink to &quot;バッチ圧縮&quot;">​</a></h3><ol><li><strong>ツール → バッチ圧縮</strong> に移動する</li><li><strong>ファイル／フォルダを選択...</strong> をクリックして項目を選択する</li><li>選択した各項目は別々のアーカイブになります</li><li>出力の <strong>フォーマット</strong>、<strong>保存場所</strong>、ファイル名の接頭辞を構成する</li><li><strong>開始</strong> をクリックする</li></ol><h3 id="バッチフォーマット変換" tabindex="-1">バッチフォーマット変換 <a class="header-anchor" href="#バッチフォーマット変換" aria-label="Permalink to &quot;バッチフォーマット変換&quot;">​</a></h3><ol><li><strong>ツール → バッチフォーマット変換</strong> に移動する</li><li><strong>ファイルを追加...</strong> をクリックして元のアーカイブを選択する</li><li><strong>ターゲットフォーマット</strong> を選択する</li><li>必要に応じて <strong>変換後に元ファイルを削除</strong> を有効にする</li><li><strong>開始</strong> をクリックする</li></ol><h3 id="バッチ暗号化-1" tabindex="-1">バッチ暗号化 <a class="header-anchor" href="#バッチ暗号化-1" aria-label="Permalink to &quot;バッチ暗号化&quot;">​</a></h3><ol><li><strong>ツール → バッチ暗号化</strong> に移動する</li><li><strong>ファイルを追加...</strong> をクリックしてアーカイブを選択する</li><li><strong>パスワード</strong> を入力する</li><li><strong>暗号化</strong> をクリックする</li></ol><h2 id="高度な機能" tabindex="-1">高度な機能 <a class="header-anchor" href="#高度な機能" aria-label="Permalink to &quot;高度な機能&quot;">​</a></h2><h3 id="アーカイブ修復-1" tabindex="-1">アーカイブ修復 <a class="header-anchor" href="#アーカイブ修復-1" aria-label="Permalink to &quot;アーカイブ修復&quot;">​</a></h3><p>破損または損傷したアーカイブを修復します：</p><ol><li>破損したアーカイブを選択する</li><li><strong>ツール → アーカイブを修復</strong> に移動する</li><li>NueZip はヘッダーをスキャンし、ディレクトリを再構築し、データブロックを修復します</li><li>修復結果を確認する</li></ol><h3 id="フォーマット変換-1" tabindex="-1">フォーマット変換 <a class="header-anchor" href="#フォーマット変換-1" aria-label="Permalink to &quot;フォーマット変換&quot;">​</a></h3><p>フォーマット間でアーカイブを変換します：</p><ol><li>アーカイブを開くか、ファイルを選択する</li><li><strong>ファイル → フォーマット変換</strong> に移動する</li><li>ターゲットフォーマットと圧縮レベルを選択する</li><li>必要に応じて元のファイルを削除する</li><li><strong>変換</strong> をクリックする</li></ol><h3 id="パスワードマネージャー" tabindex="-1">パスワードマネージャー <a class="header-anchor" href="#パスワードマネージャー" aria-label="Permalink to &quot;パスワードマネージャー&quot;">​</a></h3><p>NueZip はアーカイブのパスワードをローカルのキーチェーンに安全に保存します：</p><ol><li><strong>ツール → パスワードマネージャー</strong> に移動する</li><li>保存されているすべてのパスワードを表示する</li><li>項目の追加、編集、削除を行う</li><li>一致する暗号化アーカイブを開く際、パスワードは自動的に適用されます</li></ol><h3 id="パフォーマンスベンチマーク-1" tabindex="-1">パフォーマンスベンチマーク <a class="header-anchor" href="#パフォーマンスベンチマーク-1" aria-label="Permalink to &quot;パフォーマンスベンチマーク&quot;">​</a></h3><p>システムの圧縮パフォーマンスをテストします：</p><ol><li><strong>ツール → パフォーマンスベンチマーク</strong> に移動する</li><li>テストファイルを選択する（またはデフォルトを使用する）</li><li><strong>テスト</strong> をクリックする</li><li>圧縮／展開速度と評価を含む結果を表示する</li></ol><h3 id="アーカイブ検索-1" tabindex="-1">アーカイブ検索 <a class="header-anchor" href="#アーカイブ検索-1" aria-label="Permalink to &quot;アーカイブ検索&quot;">​</a></h3><p>アーカイブ内のファイルを検索します：</p><ol><li>アーカイブを開く</li><li><code>Cmd+F</code> を押すか、検索アイコンをクリックする</li><li>ファイル名を入力し、必要に応じて大文字小文字の区別や単語全体への一致を行う</li><li>検索結果を参照し、クリックして移動する</li></ol><h2 id="キーボードショートカット" tabindex="-1">キーボードショートカット <a class="header-anchor" href="#キーボードショートカット" aria-label="Permalink to &quot;キーボードショートカット&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ショートカット</th><th>操作</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>アーカイブを開く</td></tr><tr><td><code>Cmd+N</code></td><td>新規アーカイブ</td></tr><tr><td><code>Cmd+E</code></td><td>展開</td></tr><tr><td><code>Cmd+F</code></td><td>アーカイブ内を検索</td></tr><tr><td><code>Cmd+,</code></td><td>設定を開く</td></tr><tr><td><code>Cmd+W</code></td><td>ウィンドウを閉じる</td></tr><tr><td><code>Cmd+Q</code></td><td>アプリケーションを終了</td></tr><tr><td><code>Cmd+↑</code></td><td>1 つ上の階層へ移動</td></tr><tr><td><code>Cmd+→</code></td><td>前に進む</td></tr></tbody></table><h2 id="設定" tabindex="-1">設定 <a class="header-anchor" href="#設定" aria-label="Permalink to &quot;設定&quot;">​</a></h2><p><strong>NueZip → 設定</strong> から、または <code>Cmd+,</code> を押して設定にアクセスします：</p><ul><li><strong>一般</strong>: 言語、ログイン時の起動、外観テーマ</li><li><strong>圧縮</strong>: デフォルトフォーマット、圧縮レベル、分割サイズ</li><li><strong>展開</strong>: デフォルトの出力先、フォルダで囲む動作、競合解決</li><li><strong>フォルダアクセス</strong>: フォルダの権限とブックマークを管理する</li><li><strong>詳細</strong>: ハードウェアアクセラレーション、スレッド数、一時ディレクトリ</li><li><strong>プライバシー</strong>: データ収集の設定</li></ul>',85)])])}const b=i(r,[["render",e]]);export{u as __pageData,b as default};
